import { Icon, Stack, Text } from '@grafana/ui';

export function FiringCount({ count }: { count: number }) {
  if (count === 0) {
    return null;
  }
  return (
    <Text color="error" variant="bodySmall" tabular>
      <Stack direction="row" gap={0.25} alignItems="center">
        <Icon name="exclamation-circle" size="xs" />
        {count}
      </Stack>
    </Text>
  );
}

export function PendingCount({ count }: { count: number }) {
  if (count === 0) {
    return null;
  }
  return (
    <Text color="warning" variant="bodySmall" tabular>
      <Stack direction="row" gap={0.25} alignItems="center">
        <Icon name="circle" size="xs" />
        {count}
      </Stack>
    </Text>
  );
}
